def refs():
    return [{**s, "subject": "science", "locator": "光合作用原料與產物、葉綠體、光照／二氧化碳控制與澱粉檢測", "observedPattern": "公開公立學校生物資料常用遮光、碘液檢測、氣體判讀與原料／產物配對，要求從實驗步驟和對照推論；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bc-iv-3-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供光合作用原料、產物、葉綠體與探究設計的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "植物進行光合作用時，主要把哪兩種原料轉成醣類養分並釋放氧氣？", {"A": "二氧化碳與水", "B": "氧氣與葡萄糖", "C": "蛋白質與氧氣", "D": "二氧化碳與脂肪"}, "A", "光合作用以二氧化碳和水為主要原料，在光能參與下合成醣類並釋放氧氣，選 A。", "先把方程式中的原料、產物與能量來源分開配對。", ["列出題目要求的原料。", "二氧化碳提供碳來源，水提供氫等成分。", "光能驅動合成有機物的過程。", "氧氣是常見釋出產物，不是此題的主要原料。", "所以選 A。"], "easy"),
    make(2, "葉片細胞中的哪個構造含有葉綠素，是光合作用主要場所？", {"A": "葉綠體", "B": "細胞核", "C": "液泡", "D": "粒線體"}, "A", "葉綠體含有葉綠素與進行光合作用所需的構造；粒線體主要與呼吸作用相關，選 A。", "先辨認題目問的是光能捕捉與養分合成，而不是細胞控制或呼吸作用。", ["找出與光能吸收有關的色素。", "葉綠素位於葉綠體。", "葉綠體是植物細胞進行光合作用的主要場所。", "粒線體的主要功能不同。", "因此選 A。"], "easy"),
    make(3, "將葉片的一部分用不透光紙包住，照光數小時後用碘液處理。若只有未遮光處呈藍黑色，最能支持哪項結論？", {"A": "光照是該葉片形成可被檢出的澱粉的重要條件", "B": "遮光處製造了更多氧氣", "C": "碘液本身會把所有葉片變成澱粉", "D": "光照會使葉綠素完全消失"}, "A", "碘液可檢測澱粉；未遮光處呈藍黑色而遮光處沒有，支持光照有助於形成澱粉，選 A。", "先辨認檢測指標，再把遮光區與受光區作同葉對照。", ["先以暗處處理降低葉片原有澱粉干擾。", "只有部分區域接受光照，形成同一葉片的對照。", "碘液變藍黑表示該處有澱粉。", "結果把澱粉形成和光照條件連起來。", "所以選 A。"], "medium"),
    make(4, "若要研究二氧化碳是否為光合作用所需原料，哪種設計最適合？", {"A": "在相同光照、溫度與植物材料下，設有二氧化碳與去除二氧化碳的兩組", "B": "兩組同時改變光照、溫度與二氧化碳", "C": "只測一片葉片的顏色，不設對照", "D": "讓去除二氧化碳組完全不接觸光線"}, "A", "只改變二氧化碳可把它的影響分離；其他條件和材料相同，最後用澱粉或氣體產物比較，選 A。", "列出自變因和控制變因，避免把多個差異誤認成二氧化碳效果。", ["自變因設定為是否有二氧化碳。", "光照、溫度、水分、葉片狀態與時間固定。", "兩組都要能正常接受光照。", "用相同的澱粉檢測方法比較結果。", "因此選 A。"], "medium"),
    make(5, "光合作用製造的醣類可在植物體內轉成澱粉儲存。下列敘述何者正確？", {"A": "碘液遇到澱粉可呈藍黑色，能作為養分形成的間接證據", "B": "碘液會直接測出氧氣的體積", "C": "看到藍黑色就能證明葉片沒有呼吸作用", "D": "澱粉是植物從土壤直接吸收的成品"}, "A", "碘液與澱粉呈藍黑色，可作為葉片形成澱粉的檢測證據，但不能由此判斷呼吸停止，選 A。", "先確認檢測物質，再限制結論範圍，不把單一實驗證據擴大解讀。", ["辨認碘液的指示對象是澱粉。", "澱粉是光合作用形成的醣類可轉換的儲存形式。", "藍黑色表示檢測到澱粉。", "這個結果不直接測量氧氣，也不否定呼吸。", "所以選 A。"], "easy"),
    make(6, "水生植物在光下冒出的氣泡可用來研究光合作用，但若要比較不同光照強度，哪個量較適合作為反應指標？", {"A": "固定時間內產生的氣泡數或氧氣體積", "B": "植物盆子的顏色", "C": "實驗者的姓名", "D": "燈具標籤上的品牌"}, "A", "固定時間內的產氣量能反映氧氣釋放速率，適合比較光照強度；其他選項不是反應量，選 A。", "找能隨反應改變且可量化的應變因，再固定觀察時間。", ["自變因是光照強度。", "需量化光合作用產生的氧氣。", "固定時間內氣泡數或氧氣體積可作比較指標。", "容器與植物量等條件也要控制。", "所以選 A。"], "medium"),
    make(7, "葉片同時進行光合作用與呼吸作用時，若白天整體釋放氧氣，代表什麼？", {"A": "光合作用釋放的氧氣量大於呼吸作用消耗的氧氣量", "B": "葉片白天完全不呼吸", "C": "呼吸作用會製造比光合作用更多氧氣", "D": "氧氣不是由光合作用產生"}, "A", "植物白天仍會呼吸；若淨結果釋放氧氣，表示光合作用產氧量超過呼吸耗氧量，選 A。", "看到『淨釋放』要先扣除同時進行的呼吸作用，而不是把一個作用假設成不存在。", ["列出白天可能同時發生的兩個作用。", "光合作用產生氧氣，呼吸作用消耗氧氣。", "觀察到淨釋放表示產生量較大。", "不能因此推論呼吸停止。", "所以選 A。"], "hard"),
    make(8, "一片葉子被遮光後沒有呈藍黑色。僅依此結果，哪個說法最謹慎？", {"A": "在此實驗條件下未檢出澱粉，不能單獨證明葉片完全沒有其他醣類", "B": "遮光一定使葉片死亡", "C": "碘液能證明葉片沒有呼吸作用", "D": "遮光區一定沒有任何化學反應"}, "A", "碘液結果主要說明是否檢出澱粉；不能把未呈色擴大成葉片死亡或沒有其他代謝，選 A。", "把檢測方法能回答的問題與不能回答的問題分開。", ["確認碘液針對的是澱粉。", "未呈藍黑代表在檢測條件下澱粉未達可見程度。", "葉片仍可能有呼吸或其他代謝。", "因此不能直接宣稱沒有任何反應。", "最謹慎的敘述是 A。"], "hard"),
    make(9, "下列哪項最能表達光合作用的能量轉換？", {"A": "把光能轉成儲存在醣類中的化學能", "B": "把化學能轉成聲音而不形成物質", "C": "把氧氣轉成光能", "D": "把土壤熱能直接變成葉綠素"}, "A", "光合作用利用光能合成醣類，將能量儲存在化學鍵中，選 A。", "先找能量來源，再追蹤它最後儲存在哪一類物質中。", ["光是主要能量來源。", "葉綠體捕捉光能並驅動合成反應。", "醣類含有可供後續代謝使用的化學能。", "這是光能到化學能的轉換。", "所以選 A。"], "easy"),
    make(10, "某實驗發現強光組的產氧量反而低於中等光組。哪項解釋最合理且需要進一步驗證？", {"A": "強光可能造成光抑制或提高溫度，需控制並測量相關因素", "B": "光越強植物就必定停止所有呼吸", "C": "產氧量較低證明葉綠體消失", "D": "只要看到一次結果就能否定光合作用需要光"}, "A", "產氧量下降可能與光抑制、葉片升溫或其他條件有關；需控制溫度並做重複試驗，不能直接下單一結論，選 A。", "遇到反常資料先列出可檢驗機制，再檢查是否有混淆變因。", ["確認中等光與強光的產氧差異。", "光強改變可能同時改變葉片溫度。", "強光也可能使光合作用系統受抑。", "需固定溫度、重複測量並設合適對照。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {o["id"]: o["text"] for o in q["options"]}
    old["A"], old[target] = old[target], old["A"]
    q["options"] = [{"id": k, "text": old[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("所以選 A", f"所以選 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
